%% public_key's certificate functions (plan 21 step LIB80D1): name normalisation and issuer checks, issuer and
%% subject ids, fixed DH certificates, CRL issuers and signatures, distribution points and hostname verification.
%% The certificates and the CRL were made once with OpenSSL: a CA, a leaf with many subject alternative names, a
%% plain certificate the CRL revokes and a DH certificate.
-module(public_key_certs).
-export([main/1]).

-include_lib("public_key/include/public_key.hrl").

main(_) ->
    Data = data(),
    [Ca, Leaf, Plain, Dh, Crl] = [proplists:get_value(K, Data) || K <- [ca, leaf, plain, dh, crl]],
    names(Ca, Leaf),
    certificates(Ca, Leaf, Plain, Dh),
    crls(Ca, Leaf, Plain, Crl),
    hostnames(Leaf, Plain),
    io:format("public_key_certs: ok~n").

%% A call's result, or its exception.
safe(Fun) ->
    try
        {ok, Fun()}
    catch
        Class:Reason -> {Class, Reason}
    end.

otp(Der) -> public_key:pkix_decode_cert(Der, otp).

tbs(Der) -> (otp(Der))#'OTPCertificate'.tbsCertificate.

names(Ca, Leaf) ->
    Issuer = (tbs(Leaf))#'OTPTBSCertificate'.issuer,
    io:format("normalize ~p~n", [public_key:pkix_normalize_name(Issuer)]),
    Plain = public_key:pkix_decode_cert(Ca, plain),
    PlainSubject = (Plain#'Certificate'.tbsCertificate)#'TBSCertificate'.subject,
    io:format("normalize der ~p~n", [public_key:pkix_normalize_name(public_key:der_encode('Name', PlainSubject))]),
    Printable =
        {rdnSequence, [
            [#'AttributeTypeAndValue'{type = ?'id-at-commonName', value = {printableString, "  Mixed   Case  Name "}}],
            [#'AttributeTypeAndValue'{type = ?'id-at-countryName', value = "SE"}],
            [#'AttributeTypeAndValue'{type = ?'id-at-organizationName', value = {printableString, "One"}}],
            [#'AttributeTypeAndValue'{type = ?'id-at-localityName', value = {utf8String, <<"  Spaced  Out ">>}}]
        ]},
    io:format("normalize printable ~p~n", [public_key:pkix_normalize_name(Printable)]),
    Same =
        {rdnSequence, [
            [#'AttributeTypeAndValue'{type = ?'id-at-commonName', value = {utf8String, <<"mixed case name">>}}],
            [#'AttributeTypeAndValue'{type = ?'id-at-countryName', value = "se"}],
            [#'AttributeTypeAndValue'{type = ?'id-at-organizationName', value = "ONE"}],
            [#'AttributeTypeAndValue'{type = ?'id-at-localityName', value = {utf8String, <<"spaced out">>}}]
        ]},
    {rdnSequence, Short} = Same,
    io:format("issuer names ~p~n", [
        [
            clause_is_issuer(A, B)
         || {A, B} <- [
                {Printable, Same},
                {Same, Printable},
                {Printable, {rdnSequence, lists:sublist(Short, 3)}},
                {{rdnSequence, lists:sublist(Short, 3)}, Printable},
                {Printable, Printable}
            ]
        ]
    ]).

%% Whether a certificate with issuer A is issued by one with subject B, through pkix_is_issuer/2.
clause_is_issuer(A, B) ->
    Tbs = #'OTPTBSCertificate'{issuer = A, subject = A},
    Candidate = #'OTPTBSCertificate'{issuer = B, subject = B},
    public_key:pkix_is_issuer(#'OTPCertificate'{tbsCertificate = Tbs}, #'OTPCertificate'{tbsCertificate = Candidate}).

certificates(Ca, Leaf, Plain, Dh) ->
    Certs = [{ca, Ca}, {leaf, Leaf}, {plain, Plain}],
    [
        io:format(
            "~p~n  self ~p fixed_dh ~p~n  issuer by ca ~p ~p~n  issuer_id self ~p~n  issuer_id other ~p~n  subject ~p~n",
            [
                Name,
                public_key:pkix_is_self_signed(Der),
                public_key:pkix_is_fixed_dh_cert(Der),
                public_key:pkix_is_issuer(Der, Ca),
                public_key:pkix_is_issuer(otp(Der), otp(Ca)),
                public_key:pkix_issuer_id(Der, self),
                public_key:pkix_issuer_id(otp(Der), other),
                public_key:pkix_subject_id(Der)
            ]
        )
     || {Name, Der} <- Certs
    ],
    io:format("dh der ~p ~p~n", [
        safe(fun() -> public_key:pkix_is_fixed_dh_cert(Dh) end), safe(fun() -> public_key:pkix_is_self_signed(Dh) end)
    ]),
    [
        io:format("fixed dh ~p~n", [public_key:pkix_is_fixed_dh_cert(dh_cert(Extensions))])
     || Extensions <- [
            asn1_NOVALUE,
            [#'Extension'{extnID = ?'id-ce-keyUsage', critical = true, extnValue = [keyAgreement]}],
            [#'Extension'{extnID = ?'id-ce-keyUsage', critical = true, extnValue = [digitalSignature]}]
        ]
    ],
    io:format("issuer of ca ~p~n", [public_key:pkix_is_issuer(Ca, Leaf)]),
    io:format("issuer_id bad ~p~n", [safe(fun() -> public_key:pkix_issuer_id(Leaf, nobody) end)]).

%% A certificate of a DH key with extensions.
dh_cert(Extensions) ->
    Info = #'OTPSubjectPublicKeyInfo'{
        algorithm = #'PublicKeyAlgorithm'{algorithm = ?'dhpublicnumber', parameters = asn1_NOVALUE},
        subjectPublicKey = 1234
    },
    #'OTPCertificate'{tbsCertificate = #'OTPTBSCertificate'{subjectPublicKeyInfo = Info, extensions = Extensions}}.

crls(Ca, Leaf, Plain, Crl) ->
    Decoded = public_key:der_decode('CertificateList', Crl),
    io:format("crl issuer ~p~n  ~p~n", [public_key:pkix_crl_issuer(Crl), public_key:pkix_crl_issuer(Decoded)]),
    io:format("crl verify ~p ~p ~p ~p~n", [
        public_key:pkix_crl_verify(Crl, Ca),
        public_key:pkix_crl_verify(Decoded, otp(Ca)),
        public_key:pkix_crl_verify(Crl, Leaf),
        safe(fun() -> public_key:pkix_crl_verify(Crl, Plain) end)
    ]),
    io:format("crl is_issuer ~p ~p~n", [
        public_key:pkix_is_issuer(Decoded, Ca), public_key:pkix_is_issuer(Decoded, Leaf)
    ]),
    [
        io:format("dist_point ~p~n  ~p~n  ~p~n", [
            Name,
            public_key:pkix_dist_point(Der),
            public_key:pkix_dist_points(Der)
        ])
     || {Name, Der} <- [{leaf, Leaf}, {plain, Plain}]
    ],
    Points = [
        public_key:pkix_dist_point(Leaf),
        hd(public_key:pkix_dist_points(Leaf)),
        #'DistributionPoint'{distributionPoint = asn1_NOVALUE},
        #'DistributionPoint'{distributionPoint = {fullName, [{uniformResourceIdentifier, "http://CRL.example.com/x"}]}},
        #'DistributionPoint'{distributionPoint = {fullName, [{uniformResourceIdentifier, "http://other.example/x"}]}},
        #'DistributionPoint'{distributionPoint = {fullName, [{dNSName, "crl.example.com"}]}}
    ],
    io:format("match_dist_point ~p~n", [[public_key:pkix_match_dist_point(Crl, Point) || Point <- Points]]),
    NoIdp = Decoded#'CertificateList'{
        tbsCertList = (Decoded#'CertificateList'.tbsCertList)#'TBSCertList'{crlExtensions = asn1_NOVALUE}
    },
    io:format("match_dist_point no idp ~p~n", [public_key:pkix_match_dist_point(NoIdp, lists:last(Points))]).

hostnames(Leaf, Plain) ->
    Ids = [
        [{dns_id, "leaf.example.com"}],
        [{dns_id, "www.example.org"}],
        [{dns_id, "WWW.EXAMPLE.ORG"}],
        [{dns_id, "a.example.com"}],
        [{dns_id, <<"www.example.org">>}],
        [{uri_id, "https://svc.example.com/path"}],
        [{uri_id, "https://www.example.org/other"}],
        [{uri_id, "http://www.example.org/"}],
        [{ip, {127, 0, 0, 1}}],
        [{ip, "127.0.0.1"}],
        [{ip, {0, 0, 0, 0, 0, 0, 0, 1}}],
        [{ip, "::1"}],
        [{ip, "10.0.0.1"}],
        [{srv_id, "_xmpp.example.com"}],
        [{dns_id, "nothing.example"}, {dns_id, "www.example.org"}],
        [{dns_id, "127.0.0.1"}],
        []
    ],
    [io:format("hostname ~p ~p~n", [Id, public_key:pkix_verify_hostname(Leaf, Id)]) || Id <- Ids],
    Https = public_key:pkix_verify_hostname_match_fun(https),
    Wild = [
        [{dns_id, "a.example.com"}],
        [{dns_id, "A.Example.COM"}],
        [{dns_id, "a.b.example.com"}],
        [{dns_id, "example.com"}],
        [{dns_id, "*.example.com"}],
        [{uri_id, "https://a.example.com/"}]
    ],
    [
        io:format("wildcard ~p ~p~n", [Id, public_key:pkix_verify_hostname(Leaf, Id, [{match_fun, Https}])])
     || Id <- Wild
    ],
    io:format("match_fun ~p~n", [
        [
            Https(R, P)
         || {R, P} <- [
                {{dns_id, "x.example.com"}, {dNSName, "*.example.com"}},
                {{dns_id, "x.example.com"}, {dNSName, "x*.example.com"}},
                {{dns_id, "xy.example.com"}, {dNSName, "x*.example.com"}},
                {{dns_id, "x.example.com"}, {dNSName, "*x*.example.com"}},
                {{dns_id, "x"}, {dNSName, "*"}},
                {{dns_id, ""}, {dNSName, "*.example.com"}},
                {{ip, "1.2.3.4"}, {iPAddress, [1, 2, 3, 4]}}
            ]
        ]
    ]),
    Self = self(),
    Fail = fun(Cert) ->
        Self ! {failed, element(1, Cert)},
        false
    end,
    io:format("fail_callback ~p ~p~n", [
        public_key:pkix_verify_hostname(Leaf, [{dns_id, "nope.example"}], [{fail_callback, Fail}]),
        length(flush())
    ]),
    Fqdn = fun
        ({uri_id, "custom:" ++ Host}) -> Host;
        (_) -> default
    end,
    io:format("fqdn_fun ~p ~p ~p~n", [
        public_key:pkix_verify_hostname(Leaf, [{uri_id, "custom:www.example.org"}], [{fqdn_fun, Fqdn}]),
        public_key:pkix_verify_hostname(Leaf, [{uri_id, "https://www.example.org/x"}], [{fqdn_fun, Fqdn}]),
        public_key:pkix_verify_hostname(Leaf, [{uri_id, "custom:www.example.org"}])
    ]),
    Custom = fun
        ({dns_id, "magic"}, {dNSName, _}) -> true;
        (_, _) -> default
    end,
    io:format("custom match ~p ~p~n", [
        public_key:pkix_verify_hostname(Leaf, [{dns_id, "magic"}], [{match_fun, Custom}]),
        public_key:pkix_verify_hostname(Leaf, [{dns_id, "www.example.org"}], [{match_fun, Custom}])
    ]),
    io:format("no names ~p ~p~n", [
        public_key:pkix_verify_hostname(Plain, [{dns_id, "plain"}]),
        safe(fun() -> public_key:pkix_verify_hostname_match_fun(ldap) end)
    ]).

flush() ->
    receive
        Message -> [Message | flush()]
    after 0 -> []
    end.

